def entropy_to_mnemonic(entropy: bytes) -> str:
    # R8-mnemonic-bip39 (R7-24): BIP-39 construction — entropy bits plus
    # SHA256-checksum bits (ENT/32), split into 11-bit word indexes.
    # Strengths 128..256 bits (12/15/18/21/24 words).
    if len(entropy) * 8 not in (128, 160, 192, 224, 256):
        raise ValueError("entropy must be 128/160/192/224/256 bits")
    _hash = hashlib.sha256(bytes(entropy)).digest()
    _bits = "".join(f"{_b:08b}" for _b in bytes(entropy))
    _bits += "".join(f"{_b:08b}" for _b in _hash)[:len(entropy) * 8 // 32]
    return " ".join(_BIP39_WORDS[int(_bits[_i:_i + 11], 2)] for _i in range(0, len(_bits), 11))


def validate_mnemonic(phrase) -> bool:
    # R8-mnemonic-bip39 (R7-24): wordlist membership + checksum verify.
    try:
        if not isinstance(phrase, str):
            return False
        _words = phrase.split(" ")
        if len(_words) not in (12, 15, 18, 21, 24):
            return False
        _bits = "".join(f"{_BIP39_WORDS.index(_w):011b}" for _w in _words)
    except (ValueError, AttributeError):
        return False
    _cs_len = len(_bits) // 33
    _ent_bits, _cs_bits = _bits[:-_cs_len], _bits[-_cs_len:]
    _ent = int(_ent_bits, 2).to_bytes(len(_ent_bits) // 8, "big")
    _expect = "".join(f"{_b:08b}" for _b in hashlib.sha256(_ent).digest())[:_cs_len]
    return _cs_bits == _expect


def generate_mnemonic(strength: int = 128) -> str:
    # R8-mnemonic-bip39 (R7-24): was 12 independent dictionary draws (no
    # entropy/checksum relation — rejected by standard wallet imports).
    # Now real BIP-39 from secrets-grade entropy; default 12 words.
    if strength not in (128, 160, 192, 224, 256):
        raise ValueError("strength must be one of 128/160/192/224/256")
    return entropy_to_mnemonic(secrets.token_bytes(strength // 8))

def mnemonic_to_seed(mnemonic, passphrase=""):
    kdf = PBKDF2HMAC(hashes.SHA512(), length=64, salt=("mnemonic"+passphrase).encode(), iterations=2048)
    return kdf.derive(mnemonic.encode())

def derive_wallet_from_seed(seed_bytes, path="m/44'/60'/0'/0/0"):
    # R6-wallet-derivation-fix: single HD path only; the master-IL fallback derived different wallets per install state.
    if bip32utils is None:
        sys.stderr.write("[WALLET] FATAL: bip32utils is required for seed-phrase derivation (refusing to derive an incompatible wallet)\n")
        sys.stderr.flush()
        sys.exit(1)
    master = bip32utils.BIP32Key.fromEntropy(seed_bytes)
    parts = path[2:].split('/')
    key = master
    for part in parts:
        if part.endswith("'"):
            index = int(part[:-1]) + 0x80000000
        else:
            index = int(part)
        key = key.ChildKey(index)
    priv_bytes = key.PrivateKey()
    priv_int = int.from_bytes(priv_bytes, 'big')
    priv_key = ec.derive_private_key(priv_int, ec.SECP256K1())
    pub = priv_key.public_key()
    pub_bytes = pub.public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    pub_hex = pub_bytes.hex()
    return pubkey_to_address(pub_hex), priv_bytes.hex(), pub_hex

def encrypt_private_key(priv_hex, password):
    # KEYSTORE-1: authenticated encryption (AES-256-GCM). Old format was
    # AES-128-CBC with no MAC — bit-flips in the ciphertext produced
    # different-but-plausible key blobs.
    salt = os.urandom(16)
    kdf = PBKDF2HMAC(hashes.SHA256(), length=32, salt=salt, iterations=100000)
    key = kdf.derive(password.encode())
    nonce = os.urandom(12)
    encryptor = Cipher(algorithms.AES(key), modes.GCM(nonce)).encryptor()
    encrypted = encryptor.update(priv_hex.encode()) + encryptor.finalize()
    argon_h = ph.hash(password) if ph else hashlib.sha256((password + salt.hex()).encode()).hexdigest()
    return {"salt": base64.b64encode(salt).decode(), "nonce": base64.b64encode(nonce).decode(),
            "data": base64.b64encode(encrypted + encryptor.tag).decode(), "argon2_hash": argon_h}

def decrypt_private_key(encrypted, password):
    try:
        if ph and str(encrypted.get('argon2_hash', '')).startswith('$argon2'):
            ph.verify(encrypted['argon2_hash'], password)
        elif 'argon2_hash' in encrypted:
            salt_hex = base64.b64decode(encrypted['salt']).hex()
            expected = hashlib.sha256((password + salt_hex).encode()).hexdigest()
            if not hmac.compare_digest(str(encrypted['argon2_hash']), expected):
                raise ValueError("Invalid password")
    except Exception:
        raise ValueError("Invalid password")
    salt = base64.b64decode(encrypted["salt"])
    data = base64.b64decode(encrypted["data"])
    kdf = PBKDF2HMAC(hashes.SHA256(), length=32, salt=salt, iterations=100000)
    key = kdf.derive(password.encode())
    if "nonce" in encrypted:
        # KEYSTORE-1 current format: AES-256-GCM (authenticated)
        nonce = base64.b64decode(encrypted["nonce"])
        ct, tag = data[:-16], data[-16:]
        decryptor = Cipher(algorithms.AES(key), modes.GCM(nonce, tag)).decryptor()
        try:
            return (decryptor.update(ct) + decryptor.finalize()).decode()
        except Exception:
            raise ValueError("Invalid password")
    # Legacy pre-KEYSTORE-1 wallets (iv format): AES-128-CBC, still readable
    iv = base64.b64decode(encrypted["iv"])
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv))
    decryptor = cipher.decryptor()
    decrypted = decryptor.update(data) + decryptor.finalize()
    unpadder = PKCS7(128).unpadder()
    return (unpadder.update(decrypted) + unpadder.finalize()).decode()

def get_block_reward(height):
    halvings = height // HALVING_INTERVAL
    reward = INITIAL_BLOCK_REWARD
    for _ in range(halvings):
        reward //= 2
        if reward == 0: break
    return reward


def _validated_block_reward(block: dict, canonical_minted: int):
    # R9-reward-supply (I-R8-02): the single consensus rule for block
    # rewards, used by verify_block_proof AND _append_block alike.
    # Field semantics: block['reward'] is subsidy PLUS fee transfers
    # (fees move to the winner; only the subsidy is newly minted).
    # Returns (base, fees, total) or None on ANY mismatch:
    #   fees == sum of sealed tx envelopes (no trusted total_fees),
    #   base == min(subsidy(height), max(0, MAX_SUPPLY - minted)),
    #   reward == base + fees.
    # The produce path computes identically (cap-then-add); see the
    # equivalence test. Blocks at/below genesis height carry no mint
    # (genesis identity is verified separately). Chain reset / acceptance
    # change: see R9_MIGRATION_NOTES.md.
    try:
        bid = int(block.get('id', -1))
        if bid <= 0:
            # REWARD-GENESIS-1: genesis height mints nothing; a block at
            # height <= 0 that CLAIMS a reward must be rejected (the credit
            # path pays block['reward'] before the mint counter is touched).
            if int(block.get('reward', 0) or 0) != 0 or int(block.get('total_fees', 0) or 0) != 0:
                return None
            return (0, 0, 0)
        txs = block.get('transactions', [])
        if txs is None:
            txs = []
        fees = 0
        for _tx in txs:
            if not isinstance(_tx, dict):
                return None
            fees += int(_tx.get('fee', 0) or 0)
        if int(block.get('total_fees', 0) or 0) != fees:
            return None
        subsidy = get_block_reward(bid)
        room = int(canonical_minted if canonical_minted else 0)
        room = MAX_SUPPLY - room
        if room < 0:
            room = 0
        base = subsidy if subsidy < room else room
        if int(block.get('reward', 0) or 0) != base + fees:
            return None
        return base, fees, base + fees
    except (TypeError, ValueError, OverflowError):
        return None

def _reorg_base_mint(block: dict) -> int:
    """Fix 3 (R10): the orphan-mint/adopted-mint arithmetic in ONE place.

    block['reward'] is base_reward + total_fees but only base_reward is
    newly minted (IMPORT-MINT). Both the rollback rewind and the final
    cumulative assertion must use this exact formula or the conservation
    check compares against a different number than the rewind applied."""
    try:
        return max(0, int(block.get('reward', 0) or 0)
                   - int(block.get('total_fees', 0) or 0))
    except (TypeError, ValueError):
        return 0

def get_dynamic_fee(mempool_size):
    """EIP-1559 style: no hard cap. Base fee adjusts with demand."""
    base = MIN_FEE
    if mempool_size <= 50: return base
    multiplier = min(mempool_size / 500, 100)
    return int(base * (1 + multiplier))

def get_token_creation_fee(mempool_size):
    return TOKEN_CREATION_MULTIPLIER * get_dynamic_fee(mempool_size)

def get_public_ip():
    try:
        return requests.get('https://api.ipify.org', timeout=5).json()['ip']
    except Exception:
        try:
            return requests.get('https://icanhazip.com', timeout=5).text.strip()
        except Exception:
            logger.error("Failed to determine public IP — node cannot register on the network.")
            return None

def save_peers_to_cache(peers):
    try:
        with open(PEER_CACHE_FILE, 'w') as f:
            json.dump(list(set(peers)), f, indent=2)
    except Exception as e:
        logger.error(f"[CACHE] Save peers failed: {e}")

def load_peers_from_cache():
    try:
        with open(PEER_CACHE_FILE, 'r') as f:
            return json.load(f)
    except Exception:
        return []

# ─── decode_raw_eth_transaction & compute_contract_address ──
def decode_raw_eth_transaction(raw_tx: str) -> dict:
    if raw_tx.startswith('0x'): raw_tx = raw_tx[2:]
    tx_bytes = bytes.fromhex(raw_tx)
    decoded = rlp.decode(tx_bytes)
    if len(decoded) != 9:
        raise ValueError("Only legacy transactions (9 fields) supported")
    nonce = int.from_bytes(decoded[0], 'big')
    gasPrice = int.from_bytes(decoded[1], 'big')
    gas = int.from_bytes(decoded[2], 'big')
    to = decoded[3].hex()
    to = '0x' + to if to else ''
    value = int.from_bytes(decoded[4], 'big')
    data = decoded[5].hex()
    v = int.from_bytes(decoded[6], 'big')
    r = int.from_bytes(decoded[7], 'big')
    s = int.from_bytes(decoded[8], 'big')
    chain_id = None
    if v >= 35:
        chain_id = (v - 35) // 2
    tx_hash = eth_keccak(tx_bytes).hex()
    from_addr = None
    try:
        if Account is not None:
            recovered = Account.recover_transaction(tx_bytes)
            from_addr = recovered.lower() if recovered.startswith('0x') else '0x' + recovered.lower()
    except Exception:
        from_addr = None
    return {'nonce': nonce, 'gasPrice': gasPrice, 'gas': gas, 'to': to, 'value': value, 'data': data, 'v': v, 'r': r, 's': s, 'hash': '0x'+tx_hash, 'from': from_addr, 'chainId': chain_id}

def _raw_chain_id_ok(decoded: dict) -> bool:
    # R8-chain-id: raw Ethereum transactions are valid on this chain only
    # when EIP-155-protected with chainId == CHAIN_ID. Legacy-unprotected
    # (chainId None), missing, or wrong-chain transactions are rejected at
    # every route (consensus verifier + RPC/gossip ingress) — otherwise a
    # foreign-chain signed tx replays against Munex balances. Native Munex
    # signatures need no chain binding (format is chain-specific).
    # Chain reset / acceptance-rule change: see R8_MIGRATION_NOTES.md.
    try:
        return int(decoded.get('chainId')) == CHAIN_ID
    except (TypeError, ValueError):
        return False

def _derive_token_address(tx_hash: str, owner: str, name: str, symbol: str) -> str:
    # R5-sha3-sites: verified already-closed (R4 helper); single keccak derivation pins execute, shadow, reorg-inverse, dex.
    """R4-sha3-sites: legacy token addresses derive via keccak over
    "tx_hash:owner:name:symbol" (last 20 bytes) — not NIST SHA3-256 first-20.
    Single helper used by execute, replay-shadow, and reorg-inverse so all
    three agree by construction. Test chains reset across this change."""
    return "0x" + eth_keccak(f"{tx_hash}:{owner}:{name}:{symbol}".encode()).hex()[-40:]


def _moved_value_of(tx: dict) -> int:
    # R5-sign-fail-rollback: top-level value moved by new execute; re-fetched rows carry it in the data mirror.
    try:
        _v = int(tx.get('_value_moved', 0) or 0)
    except (TypeError, ValueError):
        _v = 0
    if not _v:
        try:
            _dd = tx.get('data') or {}
            if isinstance(_dd, str):
                _dd = json.loads(_dd)
            if isinstance(_dd, dict):
                _v = int(_dd.get('_value_moved', 0) or 0)
        except (TypeError, ValueError):
            _v = 0
    return _v if _v > 0 else 0


def compute_contract_address(sender: str, nonce: int) -> str:
    sender_bytes = bytes.fromhex(sender[2:] if sender.startswith('0x') else sender)
    if rlp is None:
        raise RuntimeError("rlp library is required for compute_contract_address")
    encoded = rlp.encode([sender_bytes, nonce])
    return '0x' + eth_keccak(encoded)[-20:].hex()

def _derive_spatial_coord(creator: str, nonce: int) -> Tuple[int, int, int]:
    """Spatial Tokens V2: coordinate is derived, not client-chosen.
    Deterministic across nodes. Bounded by SPATIAL_COORD_BOUND so it is
    always inside every live maze: coordinates live in [0, 5), which a
    minimum 5x5x5 maze contains exactly (size 5 needs no larger maze).
    Spatial contracts/tokens are separate objects at these coordinates —
    they never change maze side length, volume, growth, attestation size,
    or fork weight (see MAZE-SPATIAL-SEPARATION-1). Collisions between
    tokens are permitted."""
    _c = str(creator).lower().removeprefix("0x")
    h = eth_keccak(
        b"MCXSPATIALV2"
        + int(CHAIN_ID).to_bytes(8, "big")
        + bytes.fromhex(_c)
        + int(nonce).to_bytes(32, "big")
    )
    x = int.from_bytes(h[0:8],  "big") % SPATIAL_COORD_BOUND
    y = int.from_bytes(h[8:16],  "big") % SPATIAL_COORD_BOUND
    z = int.from_bytes(h[16:24], "big") % SPATIAL_COORD_BOUND
    return (x, y, z)

def _spatial_fee_amount_ok(block: dict) -> bool:
    """Spatial Tokens V2 (T9): sealed spatial_fee_amount must equal the sum
    of FULL spatial fees (sealed producer_cut + maze_cut per tx) across the
    block's SPATIAL txs only. Guards against a producer inflating
    distributions (unbacked mint via balance_repo.add) or starving mazes,
    and against forged cuts smuggled in on non-spatial txs (excluded by
    type). Pure function of the block dict; used by verify_block_proof."""
    try:
        sealed = int(block.get("spatial_fee_amount", 0) or 0)
    except (TypeError, ValueError):
        return False
    try:
        txs = block.get("transactions", []) or []
    except Exception:
        return False
    if not isinstance(txs, list):
        return False
    total = 0
    for tx in txs:
        if not isinstance(tx, dict):
            continue
        if tx.get("tx_type") not in ("spatial_token_create",
                                      "spatial_token_transfer"):
            continue
        try:
            total += int(tx.get("fee", 0) or 0) + \
                int(tx.get("_spatial_fee_maze_cut", 0) or 0)
        except (TypeError, ValueError):
            return False
    return total == sealed

def tx_data_to_hex(d) -> str:
    # contract_call execution rewrites tx['data'] to {'raw':..., 'result':...}
    # before the tx enters a block; import-side re-exec must read 'raw'.
    if isinstance(d, dict):
        d = d.get('raw', '')
    if d is None:
        return ''
    return str(d)

def tx_data_to_bytes(d) -> bytes:
    s = tx_data_to_hex(d)
    if not s:
        return b''
    if s.startswith(('0x', '0X')):
        s = s[2:]
    try:
        return bytes.fromhex(s)
    except ValueError:
        return s.encode()

# ─── Merkle Patricia state ───────────────────────────────
def _rlp_encode_int(val: int) -> bytes:
    if val == 0:
        return b'\x00'
    return val.to_bytes((val.bit_length() + 7) // 8, 'big')

def _rlp_encode_bytes(data: bytes) -> bytes:
    if len(data) == 1 and data[0] < 0x80:
        return data
    if len(data) < 56:
        return bytes([0x80 + len(data)]) + data
    length_bytes = _rlp_encode_int(len(data))
    return bytes([0xb7 + len(length_bytes)]) + length_bytes + data

def _rlp_encode_list(items: list) -> bytes:
    payload = b''.join(items)
    if len(payload) < 56:
        return bytes([0xc0 + len(payload)]) + payload
    length_bytes = _rlp_encode_int(len(payload))
    return bytes([0xf7 + len(length_bytes)]) + length_bytes + payload

def _keccak(data: bytes) -> bytes:
    return eth_keccak(data)

class _TrieNode:
    __slots__ = ('node_type', 'encoded', 'hash')
    def __init__(self, node_type, encoded, hash_val):
        self.node_type = node_type
        self.encoded = encoded
        self.hash = hash_val

class StateTrie:
    """Hexary Merkle Patricia Trie backed by state_trie_nodes.
    Stores RLP-encoded trie nodes keyed by keccak hash.
    Falls back to a flat key-value overlay for in-flight mutations."""
    def __init__(self, db):
        self.db = db
        self._dirty: Dict[str, bytes] = {}       # key -> json-encoded value (uncommitted)
        self._node_cache: Dict[bytes, bytes] = {} # node_hash -> rlp_encoded_node

    async def get(self, key: str):
        if key in self._dirty:
            return json.loads(self._dirty[key])
        query = "SELECT node_data FROM state_trie_nodes WHERE node_hash = ?" if self.db.db_type == "sqlite" else "SELECT node_data FROM state_trie_nodes WHERE node_hash = $1"
        row = await self.db.fetchrow(query, key)
        if not row:
            return None
        try:
            return json.loads(row['node_data'])
        except Exception:
            return None

    async def put(self, key: str, value: Any):
        self._dirty[str(key)] = json.dumps(value, sort_keys=True, separators=(',', ':'))

    def _compute_root(self) -> str:
        # Pure root computation over the current _dirty set (no DB writes).
        # R8-snapshot-restore (R7-04): validate-before-apply needs the
        # candidate root WITHOUT persisting nodes; commit() below persists
        # exactly what this computes. MERKLE-1b odd-promote rule shared.
        if not self._dirty:
            return STATE_TREE_EMPTY_HASH
        # Build sorted (leaf_hash, leaf_rlp) pairs, one per dirty key.
        # Leaf preimage is RLP([key_bytes, value_bytes]); leaf hash is keccak of it.
        pairs: List[Tuple[bytes, bytes]] = []
        for key in sorted(self._dirty):
            key_bytes = key.encode()
            value_bytes = self._dirty[key].encode() if isinstance(self._dirty[key], str) else self._dirty[key]
            leaf_rlp = _rlp_encode_list([_rlp_encode_bytes(key_bytes), _rlp_encode_bytes(value_bytes)])
            pairs.append((_keccak(leaf_rlp), leaf_rlp))
        pairs.sort(key=lambda p: p[0])
        # Build a balanced binary Merkle tree over sorted leaf hashes.
        # MERKLE-1b: odd nodes PROMOTE unchanged (no Bitcoin-style
        # self-duplication).
        level: List[bytes] = [lh for lh, _ in pairs]
        records: List[Tuple[str, str]] = []
        for lh, lr in pairs:
            records.append(('0x' + lh.hex(),
                            json.dumps({"kind": "leaf", "rlp": lr.hex()}, sort_keys=True)))
        while len(level) > 1:
            carry = level.pop() if len(level) % 2 == 1 else None
            nxt: List[bytes] = []
            for i in range(0, len(level), 2):
                parent = _keccak(level[i] + level[i + 1])
                nxt.append(parent)
                records.append(('0x' + parent.hex(),
                                json.dumps({"kind": "internal",
                                            "left": '0x' + level[i].hex(),
                                            "right": '0x' + level[i + 1].hex()},
                                           sort_keys=True, separators=(',', ':'))))
            if carry is not None:
                nxt.append(carry)
            level = nxt
        return '0x' + level[0].hex(), records

    async def commit(self) -> str:
        """Write dirty nodes inside their own local transaction and return the root.

        R6-statetrie-dirty-clear: this method NO LONGER clears _dirty
        (chain reset: state-machine change). Clearing inside the local
        transaction lost the dirt when an OUTER transaction rolled back
        afterwards, so a retry rebuilt a wrong root. Callers must invoke
        mark_committed() only after their outer transaction has exited
        successfully; produce_block does so (other single-shot callers
        such as genesis/snapshot-restore rewrite identical keys, which
        is harmless without it).
        Scope (R7-07): the root commits exactly this call's write set
        (STATE_COMMITMENT_SCOPE=two-key: height + winner balance) —
        deterministic across nodes by construction (sorted keys), NOT a
        full-state accumulator. Verifiers recompute from the same writes.
        """
        if not self._dirty:
            return STATE_TREE_EMPTY_HASH

        # R5-statetrie-batch-commit: node writes are atomic with the returned root.
        # R8-snapshot-restore: computation lives in _compute_root (shared
        # with validate-before-apply restore); this method only persists.
        root_hash, records = self._compute_root()
        _leaf_q = ("INSERT OR REPLACE INTO state_trie_nodes (node_hash,node_data,ref_count) VALUES (?,?,1)"
                   if self.db.db_type == "sqlite"
                   else "INSERT INTO state_trie_nodes (node_hash,node_data,ref_count) VALUES ($1,$2,1) "
                        "ON CONFLICT (node_hash) DO UPDATE SET node_data=$2, ref_count=state_trie_nodes.ref_count+1")
        async with await self.db.transaction():
            for _h, _d in records:
                await self.db.execute_dml(_leaf_q, _h, _d)
            return root_hash

    def mark_committed(self):
        # R6-statetrie-dirty-clear: forget dirt only after the outer
        # transaction that wrapped commit() has committed. Never call
        # this before the outer exit is known-good.
        self._dirty.clear()


# ─── Database ────────────────────────────────────────────
def _pg_convert_placeholders(query):
    """Convert ? placeholders to $N for PostgreSQL, skipping ? inside single-quoted strings."""
    result = []
    param_num = 1
    in_quote = False
    for i, c in enumerate(query):
        if in_quote:
            result.append(c)
            if c == "'" and (i == 0 or query[i - 1] != '\\'):
                in_quote = False
        elif c == "'":
            in_quote = True
            result.append(c)
        elif c == '?':
            result.append(f'${param_num}')
            param_num += 1
        else:
            result.append(c)
    return ''.join(result)

_pg_conn_context: ContextVar[Optional[Any]] = ContextVar("_pg_conn_context", default=None)
_sqlite_in_tx: ContextVar[bool] = ContextVar("_sqlite_in_tx", default=False)
# R5-sqlite-tx-task-local: transaction membership is per-task, not per-connection.


def _redact_dsn(text: str) -> str:
    """DB-BACKEND-1: strip embedded credentials (scheme://user:pass@host)
    from driver error text before logging. Userinfo without a password is
    left alone. Pure; never raises."""
    try:
        return re.sub(r"(://)([^/@\s]+)@",
                      lambda m: m.group(1) + ("***" if ":" in m.group(2) else m.group(2)) + "@",
                      str(text or ""))
    except Exception:
        return "<unprintable db error>"


class Database:
    def __init__(self, db_url=None, require_postgres=None):
        self.db_type = None
        self.conn = None
        self.cursor = None
        self._pool = None
        self._initialized = False
        self._pg_dsn = None
        self._pg_target_dsn = None
        self._db_url = db_url
        self._sqlite_lock = asyncio.Lock()
        # R5-sqlite-tx-task-local: membership lives in _sqlite_in_tx (module ContextVar).
        # R4-mainnet-guard-consistency: the effective value comes from the
        # owning node (which honors --config/--db-url); the module-level
        # CONFIG read is only the default when no node passes one.
        self.require_postgres = (require_postgres if require_postgres is not None
                                 else CONFIG.get('database', {}).get('require_postgres', False))
        if db_url:
            if db_url.startswith("sqlite://"):
                # DB-BACKEND-1: an explicit sqlite URL together with
                # require_postgres is a misconfiguration that would
                # silently split node state onto SQLite — refuse instead.
                if getattr(self, 'require_postgres', False):
                    logger.error("[DB] Explicit SQLite URL conflicts with database.require_postgres: true. Exiting.")
                    sys.exit(1)
                self.db_type = "sqlite"
                path = db_url[9:] if db_url.startswith("sqlite://") else db_url
                self.conn = sqlite3.connect(path, check_same_thread=False, timeout=30)
                self.conn.row_factory = sqlite3.Row
                self.conn.execute("PRAGMA journal_mode=WAL")
                self.conn.execute("PRAGMA synchronous=NORMAL")
                self.cursor = self.conn.cursor()
                self._initialized = True
                logger.info(f"[DB] SQLite forced (WAL): {path}")
                return
            if db_url and db_url.startswith("postgresql://") and psycopg2 is None:
                # startup bootstrap owns installs now; if we're here it was
                # skipped or pip failed — fall back to SQLite like before
                if getattr(self, 'require_postgres', False):
                    logger.error("[DB] PostgreSQL required but not available. Exiting.")
                    sys.exit(1)
                logger.warning("[DB] psycopg2 unavailable — falling back to SQLite.")
                self._fallback_sqlite()
                return
            elif db_url.startswith("postgresql://"):
                self.db_type = "postgres"
                self._pg_target_dsn = db_url
                parsed = urlparse(db_url)
                default_db = parsed._replace(path='/postgres').geturl()
                self._pg_dsn = default_db
                logger.info("[DB] PostgreSQL DSN provided.")
                return
        self._auto_detect_and_connect()

    def _auto_detect_and_connect(self):
        if psycopg2 is None:
            if getattr(self, 'require_postgres', False):
                logger.error("[DB] PostgreSQL required but not available. Exiting.")
                sys.exit(1)
            logger.warning("[DB] psycopg2 not installed — falling back to SQLite. "
                           "Install with: pip install psycopg2-binary")
            self._fallback_sqlite()
            return
        pg_user = os.environ.get("MCX_PG_USER", "postgres")
        pg_password = os.environ.get("MCX_PG_PASSWORD", "postgres")
        pg_host = os.environ.get("MCX_PG_HOST", "localhost")
        pg_port = os.environ.get("MCX_PG_PORT", "5432")
        if pg_user == "postgres" and pg_password == "postgres":
            logger.warning("[SECURITY] Using default PostgreSQL credentials (postgres:postgres). "
                          "Set MCX_PG_USER and MCX_PG_PASSWORD environment variables for production.")
        self._pg_user = pg_user; self._pg_password = pg_password; self._pg_host = pg_host; self._pg_port = pg_port
        self._pg_dsn = f"postgresql://{pg_user}:{pg_password}@{pg_host}:{pg_port}/postgres"
        self._pg_target_dsn = f"postgresql://{pg_user}:{pg_password}@{pg_host}:{pg_port}/mcx"
        try:
            conn = psycopg2.connect(self._pg_dsn)
            conn.close()
            self.db_type = "postgres"
            logger.info("[DB] PostgreSQL detected.")
        except (psycopg2.OperationalError, psycopg2.InterfaceError) as e:
            # DB-BACKEND-1: driver errors echo connection parameters — redact
            # any embedded credentials before logging.
            logger.warning(f"[DB] PostgreSQL not reachable ({_redact_dsn(str(e))})")
            if getattr(self, 'require_postgres', False):
                logger.error("[DB] PostgreSQL required but not available. Exiting.")
                sys.exit(1)
            logger.warning("[DB] Falling back to SQLite. Set database.require_postgres: true in config.yaml to make this fatal on mainnet.")
            self._fallback_sqlite()

    def _fallback_sqlite(self):
        logger.info("[DB] Falling back to SQLite.")
        self.db_type = "sqlite"
        path = os.path.join(os.getcwd(), "microcore.db")
        self.conn = sqlite3.connect(path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA journal_mode=WAL")
        self.conn.execute("PRAGMA synchronous=NORMAL")
        self.cursor = self.conn.cursor()
        self._initialized = True
        logger.info(f"[DB] SQLite connected (WAL): {path}")

    async def initialize(self):
        if self.db_type == "postgres":
            try:
                self._pool = await asyncpg.create_pool(self._pg_target_dsn, min_size=2, max_size=10)
                self._initialized = True
                logger.info("[DB] PostgreSQL connected successfully.")
                await self._apply_postgres_migrations()
                return
            except asyncpg.exceptions.InvalidCatalogNameError:
                logger.warning("[DB] Database 'mcx' does not exist. Creating...")
                conn = await asyncpg.connect(self._pg_dsn)
                await conn.execute("CREATE DATABASE mcx;")
                await conn.close()
                self._pool = await asyncpg.create_pool(self._pg_target_dsn)
                self._initialized = True
                logger.info("[DB] PostgreSQL created and connected.")
                await self._apply_postgres_migrations()
                return
            except Exception as e:
                # DB-BACKEND-1: redact before logging (see _redact_dsn).
                logger.error(f"[DB] PostgreSQL connection failed: {_redact_dsn(str(e))}")
                if getattr(self, 'require_postgres', False):
                    logger.error("[DB] PostgreSQL required but not available. Exiting.")
                    sys.exit(1)
                self._fallback_sqlite()
        else:
            self._initialized = True

    async def _apply_postgres_migrations(self):
        try:
            async with self._pool.acquire() as conn:
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS maze_id TEXT")
                await conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_minermazes_maze_id ON minermazes(maze_id) WHERE maze_id IS NOT NULL")
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS knowledge INTEGER NOT NULL DEFAULT 0")
                await conn.execute("ALTER TABLE miners ADD COLUMN IF NOT EXISTS block_signing_pub TEXT")
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS lastknowledgeheight BIGINT NOT NULL DEFAULT 0")
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS ghostx INTEGER")
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS ghosty INTEGER")
                await conn.execute("ALTER TABLE minermazes ADD COLUMN IF NOT EXISTS ghostz INTEGER")
                # Fix: REAL (float32) truncates Python float64 values on round-trip,
                # causing hash mismatches. Migrate to DOUBLE PRECISION.
                await conn.execute("ALTER TABLE blocks ALTER COLUMN coverage TYPE DOUBLE PRECISION USING coverage::DOUBLE PRECISION")
        except Exception as e:
            logger.warning(f"[DB] Postgres migration (minermazes.maze_id) skipped: {e}")


    async def close(self):
        if self.db_type == "postgres" and self._pool:
            await self._pool.close()
        elif self.db_type == "sqlite" and self.conn:
            self.conn.close()
        logger.debug("[DB] Closed")

    async def execute(self, query, *args):
        if self.db_type == "postgres":
            if "?" in query:
                query = _pg_convert_placeholders(query)
            conn = _pg_conn_context.get()
            if conn is not None:
                return await conn.fetch(query, *args)
            async with self._pool.acquire() as conn:
                return await conn.fetch(query, *args)
        else:
            async with self._sqlite_lock:
                self.cursor.execute(query, args)
                return self.cursor.fetchall()

    async def execute_dml(self, query, *args):
        if self.db_type == "postgres":
            if "?" in query:
                query = _pg_convert_placeholders(query)
            conn = _pg_conn_context.get()
            if conn is not None:
                return await conn.execute(query, *args)
            async with self._pool.acquire() as conn:
                return await conn.execute(query, *args)
        else:
            if _sqlite_in_tx.get():
                self.cursor.execute(query, args)
                return str(self.cursor.rowcount)
            async with self._sqlite_lock:
                self.cursor.execute(query, args)
                self.conn.commit()
                return str(self.cursor.rowcount)

    async def fetch(self, query, *args):
        if self.db_type == "postgres":
            if "?" in query:
                query = _pg_convert_placeholders(query)
            conn = _pg_conn_context.get()
            if conn is not None:
                rows = await conn.fetch(query, *args)
                return [dict(r) for r in rows]
            async with self._pool.acquire() as conn:
                rows = await conn.fetch(query, *args)
                return [dict(r) for r in rows]
        else:
            if _sqlite_in_tx.get():
                self.cursor.execute(query, args)
                return [dict(r) for r in self.cursor.fetchall()]
            async with self._sqlite_lock:
                self.cursor.execute(query, args)
                return [dict(r) for r in self.cursor.fetchall()]

    async def fetchrow(self, query, *args):
        if self.db_type == "postgres":
            if "?" in query:
                query = _pg_convert_placeholders(query)
            conn = _pg_conn_context.get()
            if conn is not None:
                row = await conn.fetchrow(query, *args)
                return dict(row) if row else None
            async with self._pool.acquire() as conn:
                row = await conn.fetchrow(query, *args)
                return dict(row) if row else None
        else:
            if _sqlite_in_tx.get():
                self.cursor.execute(query, args)
                row = self.cursor.fetchone()
                return dict(row) if row else None
            async with self._sqlite_lock:
                self.cursor.execute(query, args)
                row = self.cursor.fetchone()
                return dict(row) if row else None

    async def fetchval(self, query, *args):
        if self.db_type == "postgres":
            if "?" in query:
                query = _pg_convert_placeholders(query)
            conn = _pg_conn_context.get()
            if conn is not None:
                return await conn.fetchval(query, *args)
            async with self._pool.acquire() as conn:
                return await conn.fetchval(query, *args)
        else:
            if _sqlite_in_tx.get():
                self.cursor.execute(query, args)
                row = self.cursor.fetchone()
                return row[0] if row else None
            async with self._sqlite_lock:
                self.cursor.execute(query, args)
                row = self.cursor.fetchone()
                return row[0] if row else None

    async def commit(self):
        if self.db_type != "postgres":
            if _sqlite_in_tx.get():
                self.conn.commit()
            else:
                async with self._sqlite_lock:
                    self.conn.commit()

    async def rollback(self):
        if self.db_type != "postgres":
            if _sqlite_in_tx.get():
                self.conn.rollback()
            else:
                async with self._sqlite_lock:
                    self.conn.rollback()

    class _sqlite_transaction:
        def __init__(self, db):
            self._db = db
            self._nested = False
        async def __aenter__(self):
            if self._db.db_type == "sqlite":
                if not _sqlite_in_tx.get():
                    await self._db._sqlite_lock.acquire()
                    _sqlite_in_tx.set(True)
                    self._db.conn.execute("BEGIN IMMEDIATE")
                    self._nested = False
                else:
                    self._nested = True
            return self
        async def __aexit__(self, exc_type, exc_val, exc_tb):
            if self._db.db_type == "sqlite":
                if not self._nested:
                    try:
                        if exc_type:
                            self._db.conn.rollback()
                        else:
                            self._db.conn.commit()
                    finally:
                        _sqlite_in_tx.set(False)
                        self._db._sqlite_lock.release()
            return False

    class _pg_transaction:
        """PG-1: asyncpg transaction bound to a pooled connection via ContextVar."""
        def __init__(self, db):
            self._db = db
            self._conn = None
            self._tx = None
            self._token = None
            self._nested = False
        async def __aenter__(self):
            current_conn = _pg_conn_context.get()
            if current_conn is not None:
                self._conn = current_conn
                self._nested = True
                self._tx = self._conn.transaction()
                await self._tx.start()
            else:
                self._conn = await self._db._pool.acquire()
                self._tx = self._conn.transaction()
                await self._tx.start()
                self._token = _pg_conn_context.set(self._conn)
            return self
        async def __aexit__(self, exc_type, exc_val, exc_tb):
            try:
                if exc_type:
                    await self._tx.rollback()
                else:
                    await self._tx.commit()
            finally:
                if not self._nested:
                    if self._token is not None:
                        _pg_conn_context.reset(self._token)
                    await self._db._pool.release(self._conn)
            return False

    async def transaction(self):
        # PG-1: return the driver-appropriate context. The old code always
        # returned the sqlite context manager (BEGIN IMMEDIATE), which is
        # invalid against asyncpg.
        if getattr(self, "db_type", "sqlite") == "postgres":
            return self._pg_transaction(self)
        return self._sqlite_transaction(self)

